f32x3 spark_ycocg_to_rgb(f32x4 ycocg) {
    f32 Co = ycocg.r;
    f32 Cg = ycocg.g;
    f32 scale = ycocg.b;
    f32 Y = ycocg.a;

    #if SPK_BC3_YCOCG_WAVEREN
        scale = 1.0 / ((scale * (255.0 / 8.0)) + 1.0);
    #endif

    Co = (Co - cocg_offset) * scale;
    Cg = (Cg - cocg_offset) * scale;

    return saturate(f32x3(Y + Co - Cg, Y + Cg, Y - Co - Cg));
}
